// Package config renders FactorioServer settings into the JSON files read by
// the Factorio server.
package config

import (
	"encoding/json"
	"fmt"

	apiextensionsv1 "k8s.io/apiextensions-apiserver/pkg/apis/apiextensions/v1"

	gamesv1alpha1 "github.com/streamixs/factorio/apps/agent/api/v1alpha1"
)

// Names of the files generated by this package. They match the files Factorio
// reads from its config directory.
const (
	ServerSettingsFile = "server-settings.json"
	MapGenSettingsFile = "map-gen-settings.json"
	MapSettingsFile    = "map-settings.json"
)

// ServerSecretValues holds the secret material referenced by the server
// settings. The controller resolves the referenced Secret keys before
// rendering, so secret values never enter the custom resource.
type ServerSecretValues struct {
	GamePassword string
	Password     string
	Token        string
}

// render merges typed overrides and raw settings onto the Factorio defaults.
// Factorio requires the complete property tree, so the defaults are the base
// document rather than an empty object.
func render(
	defaults, overrides map[string]any,
	raw *apiextensionsv1.JSON,
) ([]byte, error) {
	settings := deepCopyMap(defaults)
	mergeMaps(settings, overrides)

	if err := mergeRaw(settings, overrides, raw); err != nil {
		return nil, err
	}

	data, err := json.MarshalIndent(settings, "", "  ")
	if err != nil {
		return nil, fmt.Errorf("marshal settings: %w", err)
	}

	return append(data, '\n'), nil
}

func deepCopyMap(source map[string]any) map[string]any {
	copied := make(map[string]any, len(source))
	for key, value := range source {
		copied[key] = deepCopyValue(value)
	}
	return copied
}

func deepCopyValue(value any) any {
	switch typed := value.(type) {
	case map[string]any:
		return deepCopyMap(typed)
	case []any:
		copied := make([]any, len(typed))
		for i, item := range typed {
			copied[i] = deepCopyValue(item)
		}
		return copied
	default:
		return value
	}
}

// mergeMaps recursively overlays source onto destination. Objects are merged
// key by key, while lists and scalars replace the destination value.
func mergeMaps(destination, source map[string]any) {
	for key, value := range source {
		sourceMap, sourceIsMap := value.(map[string]any)
		if sourceIsMap {
			if destinationMap, ok := destination[key].(map[string]any); ok {
				mergeMaps(destinationMap, sourceMap)
				continue
			}
		}

		destination[key] = deepCopyValue(value)
	}
}

// sensitiveServerRawKeys are server-settings.json secrets that must be stored
// in the managed credentials Secret instead of the custom resource.
var sensitiveServerRawKeys = map[string]struct{}{
	"game_password": {},
	"password":      {},
	"token":         {},
}

func validateServerRaw(raw *apiextensionsv1.JSON) error {
	if raw == nil || len(raw.Raw) == 0 {
		return nil
	}

	var extra map[string]any
	if err := json.Unmarshal(raw.Raw, &extra); err != nil {
		return fmt.Errorf("parse raw settings: %w", err)
	}

	for key := range extra {
		if _, forbidden := sensitiveServerRawKeys[key]; forbidden {
			return fmt.Errorf(
				"setting %q must be configured through credentials", key)
		}
	}

	return nil
}

// mergeRaw adds the keys of raw to settings. A key set by a typed field is
// rejected rather than silently overwritten. Keys that only exist in the
// defaults may be overridden through raw.
func mergeRaw(
	settings, overrides map[string]any,
	raw *apiextensionsv1.JSON,
) error {
	if raw == nil || len(raw.Raw) == 0 {
		return nil
	}

	var extra map[string]any
	if err := json.Unmarshal(raw.Raw, &extra); err != nil {
		return fmt.Errorf("parse raw settings: %w", err)
	}

	for key := range extra {
		if _, exists := overrides[key]; exists {
			return fmt.Errorf("setting %q is defined both by a typed field and raw", key)
		}
	}

	mergeMaps(settings, extra)
	return nil
}

func setString(settings map[string]any, key string, value *string) {
	if value != nil {
		settings[key] = *value
	}
}

func setBool(settings map[string]any, key string, value *bool) {
	if value != nil {
		settings[key] = *value
	}
}

func setInt32(settings map[string]any, key string, value *int32) {
	if value != nil {
		settings[key] = *value
	}
}

func setInt64(settings map[string]any, key string, value *int64) {
	if value != nil {
		settings[key] = *value
	}
}

func setFloat64(settings map[string]any, key string, value *float64) {
	if value != nil {
		settings[key] = *value
	}
}

func setAllowCommands(settings map[string]any, key string, value *gamesv1alpha1.AllowCommands) {
	if value != nil {
		settings[key] = string(*value)
	}
}
